{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kerneindholdet er korrekt: lægeattest kan indhentes, og den skal belyse funktionsevnen og behovet for behandling eller henvisning. Svaret tilføjer dog, at Udbetaling Danmark kan afvise ansøgningen uden realitetsbehandling, hvis minimumskravene slet ikke er opfyldt. Det fremgår ikke af de frosne kilder. Desuden fremstilles attest og supplerende oplysninger som et ”først forsøger”-forløb, som kilderne heller ikke angiver. Det er væsentlige juridiske tilføjelser."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: attest kan indhentes ved utilstrækkelig dokumentation (praktiserende læge nævnes dog kun indirekte), funktionsevne i forhold til den ansøgte funktionsnedsættelse, og behov for fortsat behandling eller henvisning til specialist."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad lægeattesten skal beskrive."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret bruger henvisningsnumre og angiver vejledning nr. 10157 af 5. oktober 2026 som kilde. Kilden er identificerbar."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning VEJ nr. 10157 af 05/10/2026 afsnit 5.1.2 findes i det frosne materiale og er aktuel, autoritativ og anvendelig til spørgsmålet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Passagen i 5.1.2 understøtter attestindhentning, attestens indhold og journaloplysninger i særlige tilfælde. Den understøtter ikke, at Udbetaling Danmark kan afvise uden realitetsbehandling ved manglende minimumsdokumentation, og heller ikke at afvisning typisk kun er relevant i så fald, eller at man først forsøger at belyse sagen yderligere. Svaret citerer desuden henvisninger (3 og 2), der ikke svarer til den viste kilde."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en afvisningsmulighed uden realitetsbehandling ved manglende minimumskrav. Det er ikke støttet af de leverede passager eller bestemmelser (SU-bek. § 37, stk. 5 omtaler fristfastsættelse, ikke afvisning). Svaret tilføjer også en antaget rækkefølge: først supplerende belysning, afvisning kun typisk ved manglende minimum."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger ”kan” for attestindhentning og ”i særlige tilfælde” for supplerende oplysninger. Fremmøde nævnes ikke, og rubrikken kræver kun forbehold om fremmøde, hvis det omtales."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret følger ikke helt sin egen linje. Det siger, at attest eller supplerende oplysninger er den normale vej, og at afvisning ”typisk kun” er relevant ved manglende minimum. Det opstiller et ikke-kildebaseret forløb og blander ”først forsøger” med ”kan afvise”. Henvisningerne er desuden inkonsistente."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Hovedreglerne om ”kan” og ”skal” er gengivet korrekt. Men ”kan afvise”, ”typisk kun relevant” og ”mest nærliggende, at ... først forsøger” opstiller en praksis- og skønsmodalitet, som kilderne ikke har. Det gør en ikke-støttet mulighed til en antaget normalpraksis."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret dækker, at lægeattest kan indhentes, og hvad den skal beskrive, og at yderligere oplysninger kan indhentes i særlige tilfælde. Det udelader fremmødekravet og udgiftsafholdelsen, nævner ikke udtrykkeligt den praktiserende læge og tilføjer ustøttet afvisningsindhold."
    }
  },
  "overall_notes": "Svaret rammer kernen i 5.1.2, men tilføjer en ustøttet afvisning uden realitetsbehandling og en antaget praksis, som ikke findes i kilderne. Det kan derfor ikke bestå på korrekthed, støtte, tilføjelser, sammenhæng og modalitet."
}

